import React from "react";
import { Link } from "react-router-dom";

export default function Landing() {
  return (
    <div style={{ maxWidth: 1200, margin: "0 auto", padding: "6rem 2rem" }}>
      <div className="overline" style={{ marginBottom: 20 }}>The College Alumnae Network — Est. 2026</div>
      <h1 className="font-serif" style={{ fontSize: "clamp(2.5rem, 6vw, 5rem)", color: "var(--ivy)", lineHeight: 1.05, maxWidth: 900 }}>
        Where the people who built you <em>help you build what's next.</em>
      </h1>
      <p style={{ color: "var(--muted)", maxWidth: 560, margin: "2rem 0", lineHeight: 1.7 }}>
        A private, intentional space for students and alumni to find one another — for mentorship, for opportunity, for conversation that actually leads somewhere.
      </p>
      <div style={{ display: "flex", gap: 16 }}>
        <Link to="/register"><button className="btn-accent">Request Your Invitation →</button></Link>
        <Link to="/login"><button className="btn-outline">Sign In</button></Link>
      </div>
    </div>
  );
}
